//! Format step 3 to 4, generated by `cargo run migration snapshot`. Types that only reach a changed one convert on their own. Finish the changed ones (Value) where a `compile_error!` or a type mismatch points.

use crate::{v3, v4};
use graphene_resource::ResourceHash;
use migration_core::{DocumentPayloads, MigrationError, Upgrade, format_migration};
use std::collections::HashMap;

format_migration! {
	3 => 4,
	registry: v3::Registry,
	delta: v3::Delta,
	hot_op: v3::HotOp,
	session: v3::SessionState,
	document: move_values_into_blobs,
}

impl Upgrade for v3::AttributeValue {
	type Next = v4::AttributeValue;
	fn upgrade(self) -> Result<Self::Next, MigrationError> {
		let v3::AttributeValue { value, timestamp, deleted } = self;
		Ok(v4::AttributeValue {
			value: Upgrade::upgrade(value)?,
			timestamp,
			deleted,
		})
	}
}

impl Upgrade for v3::Attributes {
	type Next = v4::Attributes;
	fn upgrade(self) -> Result<Self::Next, MigrationError> {
		let v3::Attributes { entries, floor } = self;
		Ok(v4::Attributes {
			entries: entries
				.into_iter()
				.map(|(key, entry)| Ok::<_, MigrationError>((key, Upgrade::upgrade(entry)?)))
				.collect::<Result<_, MigrationError>>()?,
			floor,
		})
	}
}

impl Upgrade for v3::Delta {
	type Next = v4::Delta;
	fn upgrade(self) -> Result<Self::Next, MigrationError> {
		let v3::Delta {
			id,
			parent,
			author,
			timestamp,
			kind,
			reverse,
			attributes,
			retired_at_ms,
		} = self;
		Ok(v4::Delta {
			id,
			parent,
			author,
			timestamp,
			kind: Upgrade::upgrade(kind)?,
			reverse: reverse.into_iter().map(Upgrade::upgrade).collect::<Result<_, MigrationError>>()?,
			attributes: Upgrade::upgrade(attributes)?,
			retired_at_ms,
		})
	}
}

impl Upgrade for v3::RegistryDelta {
	type Next = v4::RegistryDelta;
	fn upgrade(self) -> Result<Self::Next, MigrationError> {
		Ok(match self {
			v3::RegistryDelta::AddNode { id, node } => v4::RegistryDelta::AddNode { id, node: Upgrade::upgrade(node)? },
			v3::RegistryDelta::RemoveNode { id, snapshot } => v4::RegistryDelta::RemoveNode {
				id,
				snapshot: Upgrade::upgrade(snapshot)?,
			},
			v3::RegistryDelta::ChangeNodeInput { id, index, new_input } => v4::RegistryDelta::ChangeNodeInput {
				id,
				index,
				new_input: Upgrade::upgrade(new_input)?,
			},
			v3::RegistryDelta::SetNodeInputs { id, inputs } => v4::RegistryDelta::SetNodeInputs {
				id,
				inputs: inputs.into_iter().map(Upgrade::upgrade).collect::<Result<_, MigrationError>>()?,
			},
			v3::RegistryDelta::SetNodeImplementation { id, implementation } => v4::RegistryDelta::SetNodeImplementation { id, implementation },
			v3::RegistryDelta::ChangeNodeAttribute { id, delta } => v4::RegistryDelta::ChangeNodeAttribute { id, delta: Upgrade::upgrade(delta)? },
			v3::RegistryDelta::ChangeNodeInputAttribute { id, index, delta } => v4::RegistryDelta::ChangeNodeInputAttribute {
				id,
				index,
				delta: Upgrade::upgrade(delta)?,
			},
			v3::RegistryDelta::SetNetworkExport { id, index, export } => v4::RegistryDelta::SetNetworkExport {
				id,
				index,
				export: export.map(Upgrade::upgrade).transpose()?,
			},
			v3::RegistryDelta::ChangeNetworkAttribute { id, delta } => v4::RegistryDelta::ChangeNetworkAttribute { id, delta: Upgrade::upgrade(delta)? },
			v3::RegistryDelta::AddNetwork { id, network } => v4::RegistryDelta::AddNetwork {
				id,
				network: Upgrade::upgrade(network)?,
			},
			v3::RegistryDelta::RemoveNetwork { id, snapshot } => v4::RegistryDelta::RemoveNetwork {
				id,
				snapshot: Upgrade::upgrade(snapshot)?,
			},
			v3::RegistryDelta::AddResource { id, entry } => v4::RegistryDelta::AddResource { id, entry: Upgrade::upgrade(entry)? },
			v3::RegistryDelta::SetResourceHash { id, hash } => v4::RegistryDelta::SetResourceHash { id, hash },
			v3::RegistryDelta::RemoveResource { id, snapshot } => v4::RegistryDelta::RemoveResource {
				id,
				snapshot: Upgrade::upgrade(snapshot)?,
			},
			v3::RegistryDelta::AddSource { id, key, source } => v4::RegistryDelta::AddSource {
				id,
				key,
				source: Upgrade::upgrade(source)?,
			},
			v3::RegistryDelta::RemoveSource { id, key } => v4::RegistryDelta::RemoveSource { id, key },
			v3::RegistryDelta::RegisterPeer { peer, user } => v4::RegistryDelta::RegisterPeer { peer, user },
			v3::RegistryDelta::ChangeDocumentAttribute { delta } => v4::RegistryDelta::ChangeDocumentAttribute { delta: Upgrade::upgrade(delta)? },
			v3::RegistryDelta::Merge { extra_parents } => v4::RegistryDelta::Merge { extra_parents },
			v3::RegistryDelta::Meta => v4::RegistryDelta::Meta,
			v3::RegistryDelta::Other(field_0) => v4::RegistryDelta::Other(Upgrade::upgrade(field_0)?),
		})
	}
}

impl Upgrade for v3::AttributeDelta {
	type Next = v4::AttributeDelta;
	fn upgrade(self) -> Result<Self::Next, MigrationError> {
		let v3::AttributeDelta { key, value } = self;
		Ok(v4::AttributeDelta {
			key,
			value: value.map(Upgrade::upgrade).transpose()?,
		})
	}
}

impl Upgrade for v3::Node {
	type Next = v4::Node;
	fn upgrade(self) -> Result<Self::Next, MigrationError> {
		let v3::Node {
			presence,
			network,
			network_timestamp,
			implementation,
			implementation_timestamp,
			inputs,
			inputs_timestamp,
			attributes,
		} = self;
		Ok(v4::Node {
			presence,
			network,
			network_timestamp,
			implementation,
			implementation_timestamp,
			inputs: inputs.into_iter().map(Upgrade::upgrade).collect::<Result<_, MigrationError>>()?,
			inputs_timestamp,
			attributes: Upgrade::upgrade(attributes)?,
		})
	}
}

