impl Upgrade for v3::NodeInput {
	type Next = v4::NodeInput;
	fn upgrade(self) -> Result<Self::Next, MigrationError> {
		Ok(match self {
			v3::NodeInput::Node { id, index } => v4::NodeInput::Node { id, index },
			v3::NodeInput::Value { value, exposed } => v4::NodeInput::Value {
				value: Upgrade::upgrade(value)?,
				exposed,
			},
			v3::NodeInput::Scope(field_0) => v4::NodeInput::Scope(field_0),
			v3::NodeInput::Import { index } => v4::NodeInput::Import { index },
			v3::NodeInput::Reflection => v4::NodeInput::Reflection,
			v3::NodeInput::Other => v4::NodeInput::Other,
		})
	}
}

