impl Upgrade for v3::Prior {
	type Next = v4::Prior;
	fn upgrade(self) -> Result<Self::Next, MigrationError> {
		Ok(match self {
			v3::Prior::Node { id, node } => v4::Prior::Node { id, node: Upgrade::upgrade(node)? },
			v3::Prior::RemovedNode { id, tombstone } => v4::Prior::RemovedNode {
				id,
				tombstone: {
					let v3::Tombstone { content, timestamp, placeholder } = tombstone;
					v4::Tombstone {
						content: Upgrade::upgrade(content)?,
						timestamp,
						placeholder,
					}
				},
			},
			v3::Prior::AbsentNode { id } => v4::Prior::AbsentNode { id },
			v3::Prior::Network { id, network } => v4::Prior::Network {
				id,
				network: Upgrade::upgrade(network)?,
			},
			v3::Prior::RemovedNetwork { id, tombstone } => v4::Prior::RemovedNetwork {
				id,
				tombstone: {
					let v3::Tombstone { content, timestamp, placeholder } = tombstone;
					v4::Tombstone {
						content: Upgrade::upgrade(content)?,
						timestamp,
						placeholder,
					}
				},
			},
			v3::Prior::AbsentNetwork { id } => v4::Prior::AbsentNetwork { id },
			v3::Prior::Resource { id, resource } => v4::Prior::Resource {
				id,
				resource: Upgrade::upgrade(resource)?,
			},
			v3::Prior::RemovedResource { id, tombstone } => v4::Prior::RemovedResource {
				id,
				tombstone: {
					let v3::Tombstone { content, timestamp, placeholder } = tombstone;
					v4::Tombstone {
						content: Upgrade::upgrade(content)?,
						timestamp,
						placeholder,
					}
				},
			},
			v3::Prior::AbsentResource { id } => v4::Prior::AbsentResource { id },
			v3::Prior::NodeField { id, presence, field } => v4::Prior::NodeField {
				id,
				presence,
				field: Upgrade::upgrade(field)?,
			},
			v3::Prior::NetworkField { id, presence, field } => v4::Prior::NetworkField {
				id,
				presence,
				field: Upgrade::upgrade(field)?,
			},
			v3::Prior::DocumentAttribute { key, previous } => v4::Prior::DocumentAttribute {
				key,
				previous: previous.map(Upgrade::upgrade).transpose()?,
			},
			v3::Prior::PeerUser { peer, previous } => v4::Prior::PeerUser { peer, previous },
		})
	}
}

impl Upgrade for v3::NodeField {
	type Next = v4::NodeField;
	fn upgrade(self) -> Result<Self::Next, MigrationError> {
		Ok(match self {
			v3::NodeField::Presence => v4::NodeField::Presence,
			v3::NodeField::Attribute { key, previous } => v4::NodeField::Attribute {
				key,
				previous: previous.map(Upgrade::upgrade).transpose()?,
			},
			v3::NodeField::Input { index, previous } => v4::NodeField::Input {
				index,
				previous: Upgrade::upgrade(previous)?,
			},
			v3::NodeField::InputAttribute { index, key, previous } => v4::NodeField::InputAttribute {
				index,
				key,
				previous: previous.map(Upgrade::upgrade).transpose()?,
			},
			v3::NodeField::Inputs { previous, inputs_timestamp } => v4::NodeField::Inputs {
				previous: previous.into_iter().map(Upgrade::upgrade).collect::<Result<_, MigrationError>>()?,
				inputs_timestamp,
			},
			v3::NodeField::Implementation { previous, implementation_timestamp } => v4::NodeField::Implementation { previous, implementation_timestamp },
		})
	}
}

impl Upgrade for v3::NetworkField {
	type Next = v4::NetworkField;
	fn upgrade(self) -> Result<Self::Next, MigrationError> {
		Ok(match self {
			v3::NetworkField::Presence => v4::NetworkField::Presence,
			v3::NetworkField::Attribute { key, previous } => v4::NetworkField::Attribute {
				key,
				previous: previous.map(Upgrade::upgrade).transpose()?,
			},
			v3::NetworkField::Exports { previous } => v4::NetworkField::Exports {
				previous: previous.into_iter().map(Upgrade::upgrade).collect::<Result<_, MigrationError>>()?,
			},
		})
	}
}

impl Upgrade for v3::Registry {
	type Next = v4::Registry;
	fn upgrade(self) -> Result<Self::Next, MigrationError> {
		let v3::Registry {
			node_instances,
			networks,
			resources,
			peer_users,
			attributes,
			removed_nodes,
			removed_networks,
			removed_resources,
		} = self;
		Ok(v4::Registry {
			node_instances: node_instances
				.into_iter()
				.map(|(key, entry)| Ok::<_, MigrationError>((key, Upgrade::upgrade(entry)?)))
				.collect::<Result<_, MigrationError>>()?,
			networks: networks
				.into_iter()
				.map(|(key, entry)| Ok::<_, MigrationError>((key, Upgrade::upgrade(entry)?)))
				.collect::<Result<_, MigrationError>>()?,
			resources: resources
				.into_iter()
				.map(|(key, entry)| Ok::<_, MigrationError>((key, Upgrade::upgrade(entry)?)))
				.collect::<Result<_, MigrationError>>()?,
			peer_users,
			attributes: Upgrade::upgrade(attributes)?,
			removed_nodes: removed_nodes
				.into_iter()
				.map(|(key, entry)| {
					Ok::<_, MigrationError>((key, {
						let v3::Tombstone { content, timestamp, placeholder } = entry;
						v4::Tombstone {
							content: Upgrade::upgrade(content)?,
							timestamp,
							placeholder,
						}
					}))
				})
				.collect::<Result<_, MigrationError>>()?,
			removed_networks: removed_networks
				.into_iter()
				.map(|(key, entry)| {
					Ok::<_, MigrationError>((key, {
						let v3::Tombstone { content, timestamp, placeholder } = entry;
						v4::Tombstone {
							content: Upgrade::upgrade(content)?,
							timestamp,
							placeholder,
						}
					}))
				})
				.collect::<Result<_, MigrationError>>()?,
			removed_resources: removed_resources
				.into_iter()
				.map(|(key, entry)| {
					Ok::<_, MigrationError>((key, {
						let v3::Tombstone { content, timestamp, placeholder } = entry;
						v4::Tombstone {
							content: Upgrade::upgrade(content)?,
							timestamp,
							placeholder,
						}
					}))
				})
				.collect::<Result<_, MigrationError>>()?,
		})
	}
}

