impl Upgrade for v3::ResourceEntry {
	type Next = v4::ResourceEntry;
	fn upgrade(self) -> Result<Self::Next, MigrationError> {
		let v3::ResourceEntry {
			presence,
			sources,
			sources_timestamp,
			hash,
			hash_timestamp,
		} = self;
		Ok(v4::ResourceEntry {
			presence,
			sources: sources
				.into_iter()
				.map(|element| {
					Ok::<_, MigrationError>({
						let (element_0, element_1) = element;
						(element_0, Upgrade::upgrade(element_1)?)
					})
				})
				.collect::<Result<_, MigrationError>>()?,
			sources_timestamp,
			hash,
			hash_timestamp,
		})
	}
}

