impl Upgrade for v3::SessionState {
	type Next = v4::SessionState;
	fn upgrade(self) -> Result<Self::Next, MigrationError> {
		let v3::SessionState {
			peer_id,
			user_id,
			head_rev,
			last_broadcast_rev,
			redo_stack,
			next_node_counter,
			last_hot_sequence,
			view_settings,
			network_view_settings,
			retired_marks,
			clock_counter,
			shared,
		} = self;
		Ok(v4::SessionState {
			peer_id,
			user_id,
			head_rev,
			last_broadcast_rev,
			redo_stack,
			next_node_counter,
			last_hot_sequence,
			view_settings: view_settings
				.into_iter()
				.map(|(key, entry)| Ok::<_, MigrationError>((key, Upgrade::upgrade(entry)?)))
				.collect::<Result<_, MigrationError>>()?,
			network_view_settings: network_view_settings
				.into_iter()
				.map(|(key, entry)| {
					Ok::<_, MigrationError>((
						key,
						entry
							.into_iter()
							.map(|(key, entry)| Ok::<_, MigrationError>((key, Upgrade::upgrade(entry)?)))
							.collect::<Result<_, MigrationError>>()?,
					))
				})
				.collect::<Result<_, MigrationError>>()?,
			retired_marks,
			clock_counter,
			shared,
		})
	}
}

impl Upgrade for v3::Value {
	type Next = v4::Value;
	fn upgrade(self) -> Result<Self::Next, MigrationError> {
		Ok(match self {
			v3::Value::None => v4::Value::None,
			v3::Value::Bool(field_0) => v4::Value::Bool(field_0),
			v3::Value::Int(field_0) => v4::Value::Int(field_0),
			v3::Value::Float(field_0) => v4::Value::Float(field_0),
			v3::Value::Str(field_0) => v4::Value::Str(field_0),
			v3::Value::Array(field_0) => v4::Value::Array(field_0.into_iter().map(Upgrade::upgrade).collect::<Result<_, MigrationError>>()?),
			v3::Value::Object(field_0) => v4::Value::Object(
				field_0
					.into_iter()
					.map(|element| {
						Ok::<_, MigrationError>({
							let (element_0, element_1) = element;
							(element_0, Upgrade::upgrade(element_1)?)
						})
					})
					.collect::<Result<_, MigrationError>>()?,
			),
		})
	}
}

/// Values whose postcard encoding reaches this many bytes move into blobs, as the live threshold had it when version 4 began.
const BLOB_THRESHOLD: usize = 1024;

/// Move large node input values into blobs, in stored order so each blob's base is the one its slot held before.
fn move_values_into_blobs(document: &mut DocumentPayloads) -> Result<(), MigrationError> {
	let mut blobs = Blobs::default();

	for record in &mut document.history {
		let mut delta: v4::Delta = record.decode()?;
		blobs.op(&mut delta.kind);
		delta.reverse.iter_mut().for_each(|prior| blobs.prior(prior));
		*record = record.encode_as(&delta)?;
	}
	for record in &mut document.hot_log {
		let mut hot_op: v4::HotOp = record.decode()?;
		blobs.op(&mut hot_op.op);
		*record = record.encode_as(&hot_op)?;
	}
	if let Some(record) = &mut document.registry {
		let mut registry: v4::Registry = record.decode()?;
		// In ID order, so which of two slots sharing a new value bases it doesn't depend on hashing
		let mut nodes: Vec<_> = registry.node_instances.iter_mut().collect();
		nodes.sort_unstable_by_key(|(id, _)| **id);
		for (id, node) in nodes {
			blobs.node(*id, node);
		}
		registry.removed_nodes.values_mut().for_each(|tombstone| blobs.loose_node(&mut tombstone.content));
		*record = record.encode_as(&registry)?;
	}

	document.blobs.extend(blobs.bytes);
	document.blob_bases.extend(blobs.bases);
	Ok(())
}

#[derive(Default)]
struct Blobs {
	bytes: HashMap<ResourceHash, Vec<u8>>,
	bases: HashMap<ResourceHash, ResourceHash>,
	/// The blob each input slot last held, by node and input index.
	latest: HashMap<(v4::NodeId, u32), ResourceHash>,
}

impl Blobs {
	fn op(&mut self, op: &mut v4::RegistryDelta) {
		match op {
			v4::RegistryDelta::AddNode { id, node } => self.node(*id, node),
			v4::RegistryDelta::RemoveNode { snapshot, .. } => self.loose_node(snapshot),
			v4::RegistryDelta::ChangeNodeInput { id, index, new_input } => self.write(*id, *index, new_input),
			v4::RegistryDelta::SetNodeInputs { id, inputs } => {
				for (index, slot) in (0..).zip(inputs) {
					self.write(*id, index, &mut slot.input);
				}
			}
			_ => {}
		}
	}

	/// Priors only restore earlier values, so they never advance a slot's latest blob.
	fn prior(&mut self, prior: &mut v4::Prior) {
		match prior {
			v4::Prior::Node { node, .. } => self.loose_node(node),
			v4::Prior::RemovedNode { tombstone, .. } => self.loose_node(&mut tombstone.content),
			v4::Prior::NodeField {
				field: v4::NodeField::Input { previous, .. },
				..
			} => {
				self.move_into_blob(&mut previous.input);
			}
			v4::Prior::NodeField {
				field: v4::NodeField::Inputs { previous, .. },
				..
			} => {
				for slot in previous {
					self.move_into_blob(&mut slot.input);
				}
			}
			_ => {}
		}
	}

	fn node(&mut self, id: v4::NodeId, node: &mut v4::Node) {
		for (index, slot) in (0..).zip(&mut node.inputs) {
			self.write(id, index, &mut slot.input);
		}
	}

	fn loose_node(&mut self, node: &mut v4::Node) {
		for slot in &mut node.inputs {
			self.move_into_blob(&mut slot.input);
		}
	}

	/// A write into an input slot, whose blob is based on the one the slot held before.
	fn write(&mut self, id: v4::NodeId, index: u32, input: &mut v4::NodeInput) {
		let Some((hash, created)) = self.move_into_blob(input) else { return };

		// Only a blob created here takes a base, which keeps bases acyclic
		if let Some(previous) = self.latest.insert((id, index), hash)
			&& created
			&& previous != hash
		{
			self.bases.insert(hash, previous);
		}
	}

	/// The blob `input` now names, and whether this call created it.
	fn move_into_blob(&mut self, input: &mut v4::NodeInput) -> Option<(ResourceHash, bool)> {
		let v4::NodeInput::Value { value, .. } = input else { return None };
		if let v4::Value::Blob(hash) = value {
			return Some((hash.0, false));
		}

		let encoded = postcard::to_stdvec(value).ok()?;
		if encoded.len() < BLOB_THRESHOLD {
			return None;
		}

		let hash = ResourceHash::from(encoded.as_slice());
		*value = v4::Value::Blob(v4::BlobHash(hash));
		let created = self.bytes.insert(hash, encoded).is_none();
		Some((hash, created))
	}
}
